-- Darkshore: creature abilities
-- Darkshore is the Cataclysm revamp, and almost none of its creatures (Shatterspear, Twilight, Darkscale, Greymist, the corrupted
-- wildlife, the Lor'danel sentinels) had AI. Port their abilities from the Cataclysm data, keeping the Darkshore Protection and
-- Blessed Herb Bundle quest scripts already in place. Teegan Holloway only takes his combat rows: his Cataclysm patrol needs a
-- waypoint path and action list mop_world does not have.

SET @ENTRIES := '2071,2165,2172,2175,2184,2186,2191,2192,2206,2233,2237,3717,3812,7015,7016,7017,32855,32858,32859,32860,32861,32862,32863,32868,32869,32888,32890,32899,32928,32935,32969,32988,32989,32990,32996,32999,33009,33020,33021,33022,33043,33044,33057,33071,33079,33083,33084,33107,33115,33117,33127,33179,33180,33206,33207,33262,33277,33311,33345,33359,33864,33905,33978,33981,34009,34033,34046,34248,34282,34302,34304,34309,34318,34326,34331,34339,34369,34385,34405,34413,34414,34415,34417,43440';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '33181,34056,34427,48763,48764';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
